import fs from 'fs';
import os from 'os';
import path from 'path';
import {
  CLI_GUIDANCE_BODY,
  CLI_GUIDANCE_VERSION,
} from '../utils/skills/cli-guidance';
import { errorMessage } from '../utils/errorMessage';


const SECTION_BEGIN = '<!-- BEGIN RIVET (written by `rivet install codex`) -->';
const SECTION_END = '<!-- END RIVET -->';

export const codexAgentsPath = (homeDir: string = os.homedir()): string =>
  path.join(homeDir, '.codex', 'AGENTS.md');

const buildSection = (): string =>
  [
    SECTION_BEGIN,
    `<!-- rivet-cli-guidance-version: ${CLI_GUIDANCE_VERSION} -->`,
    '# Rivet',
    '',
    CLI_GUIDANCE_BODY,
    SECTION_END,
  ].join('\n');

const stripSection = (contents: string): string => {
  const begin = contents.indexOf(SECTION_BEGIN);
  if (begin === -1) return contents;
  const end = contents.indexOf(SECTION_END, begin);
  if (end === -1) return contents;
  const sectionStart =
    begin > 0 && contents[begin - 1] === '\n' ? begin - 1 : begin;
  const afterMarker = end + SECTION_END.length;
  const sectionEnd =
    contents[afterMarker] === '\n' ? afterMarker + 1 : afterMarker;
  return `${contents.slice(0, sectionStart)}${contents.slice(sectionEnd)}`;
};

export const hasCodexGuidance = (homeDir: string = os.homedir()): boolean => {
  try {
    return fs
      .readFileSync(codexAgentsPath(homeDir), 'utf8')
      .includes(SECTION_BEGIN);
  } catch {
    return false;
  }
};

export type GuidanceResult =
  { ok: true; changed: boolean } | { ok: false; error: string };

export const writeCodexGuidance = (
  homeDir: string = os.homedir(),
): GuidanceResult => {
  const filePath = codexAgentsPath(homeDir);
  try {
    const existing = fs.existsSync(filePath)
      ? fs.readFileSync(filePath, 'utf8')
      : '';
    const withoutSection = stripSection(existing);
    const next = withoutSection
      ? `${withoutSection}\n${buildSection()}\n`
      : `${buildSection()}\n`;
    if (next === existing) {
      return { ok: true, changed: false };
    }
    fs.mkdirSync(path.dirname(filePath), { recursive: true });
    fs.writeFileSync(filePath, next, 'utf8');
    return { ok: true, changed: true };
  } catch (err) {
    return {
      ok: false,
      error: errorMessage(err),
    };
  }
};

export const removeCodexGuidance = (
  homeDir: string = os.homedir(),
): GuidanceResult => {
  const filePath = codexAgentsPath(homeDir);
  if (!fs.existsSync(filePath)) return { ok: true, changed: false };
  try {
    const existing = fs.readFileSync(filePath, 'utf8');
    const next = stripSection(existing);
    if (next === existing) return { ok: true, changed: false };
    if (next.trim() === '') {
      fs.unlinkSync(filePath);
    } else {
      fs.writeFileSync(filePath, next, 'utf8');
    }
    return { ok: true, changed: true };
  } catch (err) {
    return {
      ok: false,
      error: errorMessage(err),
    };
  }
};
